package opengpu.graphics

import chisel3._
import chisel3.util._
import opengpu.graphics.WindowRecordTest._
import opengpu.system._
import opengpu.graphics.tessellation._
import opengpu.testutil.GpuSim._
import org.scalatest.flatspec.AnyFlatSpec

/** The actual Owner and Publisher share the same cancel feedback as the
  * typed image parent. Only VS execution, image tasks and patch-memory replies
  * are peers; every Publisher/Owner completion is generated by its real RTL.
  */
private class VertexPatchOwnerPublisherHarness extends Module {
  private val p=VertexShaderStageConfig()
  private val owner=Module(new TessellationVertexPatchOwner(p,UInt(32.W)))
  private val publisher=Module(new TessellationVertexPatchPublisher(p))
  val io=IO(new Bundle {
    val begin=Flipped(Decoupled(chiselTypeOf(owner.io.begin.bits)))
    val imageTask=Decoupled(UInt(32.W));val opened=Flipped(Decoupled(UInt(2.W)))
    val imageCompletion=Flipped(Decoupled(new TessellationVertexPatchImageResult))
    val sourceDraw=Decoupled(new VertexShaderDraw(p))
    val sourceOut=Flipped(Decoupled(new ShadedVertexRecord(p)))
    val sourceCompletion=Flipped(Decoupled(new VertexShaderCompletion));val sourceBusy=Input(Bool())
    val load=Decoupled(new TessellationPatchAccess);val reply=Flipped(Decoupled(new TessellationContextReply))
    val seal=Decoupled(Bool());val cancel=Input(Bool());val producerCancel=Input(Bool())
    val transportDrained=Input(Bool());val frameStopped=Input(Bool())
    val cancelImage=Output(Bool());val cancelSource=Output(Bool());val cancelVertex=Output(Bool())
    val cancelPatch=Output(Bool());val sourceOwned=Output(Bool());val producerBusy=Output(Bool())
    val busy=Output(Bool());val drained=Output(Bool())
    val completion=Decoupled(new TessellationVertexPatchOwnerResult)
  })
  owner.io.begin<>io.begin;io.imageTask<>owner.io.imageTask;owner.io.opened<>io.opened
  owner.io.imageCompletion<>io.imageCompletion;io.completion<>owner.io.completion
  publisher.io.task<>owner.io.sourceTask;owner.io.sourceCompletion<>publisher.io.completion
  owner.io.sourceBusy:=publisher.io.busy;owner.io.sourcePatchCancel:=publisher.io.cancelPatch
  publisher.io.cancel:=owner.io.cancelSource || io.producerCancel
  publisher.io.sourceBusy:=io.sourceBusy;io.sourceDraw<>publisher.io.sourceDraw
  publisher.io.sourceOut<>io.sourceOut;publisher.io.sourceCompletion<>io.sourceCompletion
  io.load<>publisher.io.load;publisher.io.reply<>io.reply;io.seal<>publisher.io.seal
  owner.io.cancel:=io.cancel;owner.io.transportDrained:=io.transportDrained
  owner.io.frameStopped:=io.frameStopped
  io.cancelImage:=owner.io.cancelImage;io.cancelSource:=owner.io.cancelSource
  io.cancelVertex:=publisher.io.cancelSource;io.cancelPatch:=publisher.io.cancelPatch
  io.sourceOwned:=owner.io.sourceOwned;io.producerBusy:=publisher.io.busy
  io.busy:=owner.io.busy;io.drained:=owner.io.drained
}

/** Real controller RTL, with image and VS protocol peers; no shader execution. */
class TessellationVertexPatchOwnerSpec extends AnyFlatSpec {
  it should "retain original ownership through admission rejection, held cancellation, actual completions and local drain" in {
    simulate(new TessellationVertexPatchOwner(VertexShaderStageConfig(),UInt(32.W))){d=>
      zero(d.io);d.reset.poke(true.B);d.clock.step();d.reset.poke(false.B)
      d.io.transportDrained.poke(true.B)
      var id=BigInt("70000010",16);var image=BigInt(0);var vertex=BigInt(0)
      def until(test: =>Boolean):Unit={var n=0;while(!test && n<30){d.clock.step();n+=1};assert(test,"patch owner stalled")}
      def begin(cancel:Boolean=false):Unit={
        id+=1;image=id^BigInt("a5a5a5a5",16)
        d.io.cancel.poke(cancel.B);d.io.frameStopped.poke(false.B);d.io.sourcePatchCancel.poke(false.B)
        zero(d.io.begin.bits);val v=d.io.begin.bits.vertex
        v.version.poke(1.U);v.taskId.poke(id.U);v.layout.inputVertices.poke(32.U)
        v.layout.inputComponents.poke(64.U);v.layout.outputVertices.poke(32.U)
        v.layout.outputComponents.poke(60.U);v.layout.patchComponents.poke(120.U)
        v.draw.input.count.poke(4096.U);v.draw.input.firstIndex.poke(17.U)
        v.draw.input.firstVertex.poke(23.U);v.draw.input.baseVertex.poke((-7).S)
        v.draw.input.baseInstance.poke(19.U);v.draw.input.instances.poke(13.U)
        for(i<-0 until 16){v.draw.input.bindings(i).base.poke((0x10000+i*4096).U)
          v.draw.input.bindings(i).divisor.poke((i+1).U);v.draw.input.bindings(i).stride.poke((i*4+16).U)}
        for(i<-0 until 64){v.components(i).kind.poke(1.U);v.components(i).component.poke(i.U)}
        v.slice.version.poke(1.U);v.slice.firstOrdinal.poke(97.U);v.slice.count.poke(32.U)
        v.slice.firstInstance.poke(11.U);v.slice.instances.poke(1.U)
        d.io.begin.bits.image.poke(image.U);vertex=v.peek().litValue
        d.io.begin.valid.poke(true.B);until(d.io.begin.ready.peek().litToBoolean)
        d.clock.step();d.io.begin.valid.poke(false.B);zero(d.io.begin.bits);d.io.cancel.poke(false.B)
      }
      def acceptImage():Unit={
        until(d.io.imageTask.valid.peek().litToBoolean);d.io.imageTask.bits.expect(image.U)
        for(_<-0 until 3){d.io.imageTask.valid.expect(true.B);d.io.imageTask.bits.expect(image.U);d.clock.step()}
        d.io.imageTask.ready.poke(true.B);d.clock.step();d.io.imageTask.ready.poke(false.B)
      }
      def open(status:Int=0):Unit={
        d.io.opened.bits.poke(status.U);d.io.opened.valid.poke(true.B)
        until(d.io.opened.ready.peek().litToBoolean);d.clock.step();d.io.opened.valid.poke(false.B)
      }
      def acceptSource():Unit={
        until(d.io.sourceTask.valid.peek().litToBoolean)
        assert(d.io.sourceTask.bits.peek().litValue==vertex,"original draw, maps or slice changed")
        d.io.sourceTask.ready.poke(true.B);d.clock.step();d.io.sourceTask.ready.poke(false.B)
        d.io.sourceBusy.poke(true.B);d.io.sourceOwned.expect(true.B)
      }
      def sourceComplete(status:Int=0,tag:BigInt=id,holdBusy:Boolean=false):Unit={
        zero(d.io.sourceCompletion.bits);d.io.sourceCompletion.bits.taskId.poke(tag.U)
        d.io.sourceCompletion.bits.status.poke(status.U);d.io.sourceCompletion.bits.vertices.poke(32.U)
        d.io.sourceCompletion.bits.words.poke(2048.U);d.io.sourceCompletion.valid.poke(true.B)
        // The producer stays busy while its completion is offered.
        d.io.sourceBusy.poke(true.B);d.io.sourceCompletion.ready.expect(true.B)
        d.clock.step();d.io.sourceCompletion.valid.poke(false.B);zero(d.io.sourceCompletion.bits)
        if(!holdBusy)d.io.sourceBusy.poke(false.B)
      }
      def imageComplete(status:Int=0,published:Int=17):Unit={
        d.io.imageCompletion.bits.status.poke(status.U);d.io.imageCompletion.bits.published.poke(published.U)
        d.io.imageCompletion.valid.poke(true.B);until(d.io.imageCompletion.ready.peek().litToBoolean)
        d.clock.step();d.io.imageCompletion.valid.poke(false.B);zero(d.io.imageCompletion.bits)
      }
      def finish(status:Int,imageStatus:Int=0,published:Int=17,heldFlush:Boolean=false):Unit={
        until(d.io.completion.valid.peek().litToBoolean)
        d.io.completion.bits.taskId.expect(id.U);d.io.completion.bits.status.expect(status.U)
        d.io.completion.bits.image.status.expect(imageStatus.U);d.io.completion.bits.image.published.expect(published.U)
        d.io.begin.ready.expect(false.B);d.io.drained.expect(true.B)
        val held=d.io.completion.bits.peek().litValue;d.io.cancel.poke(true.B)
        // A later valid-only flush can lower transport drain after this
        // immutable report was offered. It cannot revoke the report or imply
        // that an already completed child has acquired another credit.
        if(heldFlush)d.io.transportDrained.poke(false.B)
        for(_<-0 until 4){d.clock.step();d.io.completion.valid.expect(true.B)
          assert(d.io.completion.bits.peek().litValue==held);d.io.drained.expect((!heldFlush).B)}
        d.io.cancel.poke(false.B);d.io.completion.ready.poke(true.B);d.clock.step()
        d.io.completion.ready.poke(false.B);d.io.busy.expect(false.B)
        if(heldFlush){d.io.begin.ready.expect(false.B);d.io.transportDrained.poke(true.B)}
      }

      // Original task snapshots and separate source, patch and local drain.
      begin();acceptImage();open()
      for(_<-0 until 4){d.io.sourceTask.valid.expect(true.B)
        assert(d.io.sourceTask.bits.peek().litValue==vertex);d.clock.step()}
      acceptSource();sourceComplete();d.clock.step(3);d.io.completion.valid.expect(false.B)
      d.io.transportDrained.poke(false.B);imageComplete()
      for(_<-0 until 4){d.clock.step();d.io.completion.valid.expect(false.B);d.io.drained.expect(false.B)}
      d.io.transportDrained.poke(true.B);finish(0,heldFlush=true)

      // A real early admission failure does not emit opened or launch VS.
      begin();acceptImage();imageComplete(1,0);d.io.sourceTask.valid.expect(false.B)
      finish(1,1,0)

      // A previously offered range task is accepted even during cancellation.
      begin(cancel=true);d.io.imageTask.valid.expect(false.B);d.io.sourceTask.valid.expect(false.B)
      finish(4,0,0)

      // Cancellation alone cannot withdraw the held image offer. Only the
      // actual terminal image report authorizes abandoning unaccepted work.
      begin();until(d.io.imageTask.valid.peek().litToBoolean)
      d.io.cancel.poke(true.B);d.clock.step();d.io.cancel.poke(false.B)
      for(_<-0 until 4){d.io.imageTask.valid.expect(true.B);d.io.imageTask.bits.expect(image.U)
        d.io.completion.valid.expect(false.B);d.io.cancelImage.expect(true.B);d.clock.step()}
      d.io.frameStopped.poke(true.B);d.io.imageTask.valid.expect(false.B);d.clock.step()
      d.io.frameStopped.poke(false.B);finish(4,0,0)

      // The VS offer still transfers after cancel, then the accepted producer
      // is canceled and its actual completion must be consumed before reuse.
      begin();acceptImage();open();d.io.cancel.poke(true.B);d.clock.step();d.io.cancel.poke(false.B)
      imageComplete(4,0)
      for(_<-0 until 4){d.io.sourceTask.valid.expect(true.B);d.io.cancelSource.expect(false.B)
        d.io.completion.valid.expect(false.B);d.clock.step()}
      acceptSource();d.io.cancelSource.expect(true.B);sourceComplete(4);finish(4,4,0)

      // Accept source completion while busy includes it, then wait for actual
      // residual child credits. A late source fault remains primary to cancel.
      begin();acceptImage();open();acceptSource()
      d.io.cancel.poke(true.B);d.clock.step();d.io.cancel.poke(false.B)
      sourceComplete(2,holdBusy=true);imageComplete(4,0)
      for(_<-0 until 4){d.clock.step();d.io.completion.valid.expect(false.B)}
      d.io.sourceBusy.poke(false.B);finish(2,4,0)

      // A patch failure cancels a still-held VS offer without revoking it.
      begin();acceptImage();open();imageComplete(2,0)
      d.io.sourceTask.valid.expect(true.B);d.io.cancelSource.expect(false.B)
      acceptSource();d.io.cancelSource.expect(true.B);sourceComplete(4);finish(1,2,0)

      // A foreign completion cannot change the original accepted taskId.
      begin();acceptImage();open();acceptSource();sourceComplete(tag=id+1)
      d.io.cancelImage.expect(true.B);imageComplete(4,0);finish(3,4,0)

      // An image cannot succeed while its original VS offer is still held.
      begin();acceptImage();open();imageComplete()
      d.io.sourceTask.valid.expect(true.B);acceptSource();sourceComplete();finish(3)

      // An accepted launch alone is not producer completion either.
      begin();acceptImage();open();acceptSource();imageComplete()
      sourceComplete();finish(3)

      // A terminal frame can also stop an unaccepted image without cancel.
      begin();until(d.io.imageTask.valid.peek().litToBoolean)
      d.io.frameStopped.poke(true.B);d.clock.step();d.io.frameStopped.poke(false.B)
      finish(1,0,0)

      // Real late image faults have the same priority over cancellation.
      begin();acceptImage();open();acceptSource()
      d.io.cancel.poke(true.B);d.clock.step();d.io.cancel.poke(false.B)
      sourceComplete(4);imageComplete(2,0);finish(1,2,0)

      begin();acceptImage();open(1);d.io.sourceTask.valid.expect(false.B)
      imageComplete(1,0);finish(1,1,0)

      begin();acceptImage();imageComplete();d.io.sourceTask.valid.expect(false.B);finish(3)

      // Both actual completions may transfer in the same cycle.
      begin();acceptImage();open();acceptSource()
      d.io.sourceCompletion.bits.taskId.poke(id.U);d.io.sourceCompletion.bits.status.poke(0.U)
      d.io.sourceCompletion.valid.poke(true.B);d.io.sourceCompletion.ready.expect(true.B)
      d.io.imageCompletion.bits.status.poke(0.U);d.io.imageCompletion.bits.published.poke(17.U)
      d.io.imageCompletion.valid.poke(true.B);d.io.imageCompletion.ready.expect(true.B)
      d.clock.step();d.io.sourceCompletion.valid.poke(false.B);zero(d.io.sourceCompletion.bits)
      d.io.imageCompletion.valid.poke(false.B);zero(d.io.imageCompletion.bits);d.io.sourceBusy.poke(false.B)
      finish(0)

      // Healthy reuse with no reset after all rejection/cancel/fault paths.
      begin();acceptImage();open();acceptSource();sourceComplete();imageComplete();finish(0)
    }
  }
  it should "drain actual Publisher cancellation feedback, faults and held offers before no-reset reuse" in {
    simulate(new VertexPatchOwnerPublisherHarness){d=>
      val io=d.io;zero(io);io.transportDrained.poke(true.B)
      d.reset.poke(true.B);d.clock.step();d.reset.poke(false.B)
      var id=100;var pending=false
      def until(done: =>Boolean,why:String):Unit={var n=0;while(!done && n<100){d.clock.step();n+=1};assert(done,why)}
      def begin(valid:Boolean=true):Unit={
        assert(!pending);id+=1;io.cancel.poke(false.B);io.producerCancel.poke(false.B)
        io.transportDrained.poke(true.B);io.frameStopped.poke(false.B)
        val t=io.begin.bits.vertex;zero(io.begin.bits);t.version.poke((if(valid)1 else 2).U)
        t.taskId.poke(id.U);t.layout.inputVertices.poke(1.U);t.layout.inputComponents.poke(1.U)
        t.layout.outputVertices.poke(32.U);t.layout.outputComponents.poke(60.U);t.layout.patchComponents.poke(120.U)
        t.draw.version.poke(1.U);t.draw.input.version.poke(1.U);identity(t.draw.input.identity)
        t.draw.input.count.poke(32.U);t.draw.input.instances.poke(1.U)
        t.draw.varyingSlots.poke(16.U);t.draw.varyingMask.poke(((BigInt(1)<<64)-1).U)
        t.slice.version.poke(1.U);t.slice.count.poke(1.U);t.slice.instances.poke(1.U)
        io.begin.bits.image.poke((0x1000+id).U);io.begin.valid.poke(true.B)
        until(io.begin.ready.peek().litToBoolean,"owner admission");d.clock.step();io.begin.valid.poke(false.B)
        zero(io.begin.bits);until(io.imageTask.valid.peek().litToBoolean,"held image offer")
        val image=io.imageTask.bits.peek().litValue
        for(_<-0 until 3){io.imageTask.valid.expect(true.B);assert(io.imageTask.bits.peek().litValue==image);d.clock.step()}
        io.imageTask.ready.poke(true.B);d.clock.step();io.imageTask.ready.poke(false.B)
        io.opened.valid.poke(true.B);io.opened.bits.poke(0.U)
        until(io.opened.ready.peek().litToBoolean,"actual opened receipt");d.clock.step();io.opened.valid.poke(false.B)
        until(io.sourceOwned.peek().litToBoolean,"real Publisher task acceptance")
      }
      def heldDraw(cancel:Boolean=false):Unit={
        until(io.sourceDraw.valid.peek().litToBoolean,"Publisher VS offer")
        val held=io.sourceDraw.bits.peek().litValue
        if(cancel){io.cancel.poke(true.B);io.cancelSource.expect(true.B);io.cancelVertex.expect(false.B)}
        for(_<-0 until 3){io.sourceDraw.valid.expect(true.B);assert(io.sourceDraw.bits.peek().litValue==held)
          io.cancelVertex.expect(false.B);d.clock.step()}
        io.sourceDraw.ready.poke(true.B);d.clock.step();io.sourceDraw.ready.poke(false.B)
        io.sourceBusy.poke(true.B)
        if(cancel)io.cancelVertex.expect(true.B)
      }
      def vertex():Unit={
        val r=io.sourceOut.bits;zero(r);identity(r.identity)
        r.position(0).poke(0x3f800000.U);io.sourceOut.valid.poke(true.B)
        until(io.sourceOut.ready.peek().litToBoolean,"actual VS stream");d.clock.step();io.sourceOut.valid.poke(false.B)
      }
      def load(cancel:Boolean=false,producer:Boolean=false):Unit={
        until(io.load.valid.peek().litToBoolean,"Publisher patch load")
        io.load.bits.vertex.expect(0.U);io.load.bits.component.expect(0.U);io.load.bits.data.expect(0x3f800000.U)
        val held=io.load.bits.peek().litValue
        if(cancel){
          if(producer){io.producerCancel.poke(true.B);io.cancelSource.expect(false.B)}else{
            io.cancel.poke(true.B);io.cancelSource.expect(true.B)
          }
          io.cancelImage.expect(true.B)
        }
        for(_<-0 until 3){io.load.valid.expect(true.B);assert(io.load.bits.peek().litValue==held);d.clock.step()}
        io.load.ready.poke(true.B);d.clock.step();io.load.ready.poke(false.B);pending=true
      }
      def reply(status:Int=0):Unit={
        assert(pending,"patch reply without an accepted load")
        for(_<-0 until 3){io.completion.valid.expect(false.B);io.begin.ready.expect(false.B);d.clock.step()}
        zero(io.reply.bits);io.reply.bits.result.status.poke(status.U);io.reply.valid.poke(true.B)
        until(io.reply.ready.peek().litToBoolean,"accepted patch reply must drain")
        d.clock.step();io.reply.valid.poke(false.B);pending=false
      }
      def sourceResult(status:Int,origin:Boolean=false):Unit={
        zero(io.sourceCompletion.bits);identity(io.sourceCompletion.bits.identity)
        io.sourceCompletion.bits.status.poke(status.U);io.sourceCompletion.bits.vertices.poke((if(status==0)1 else 0).U)
        io.sourceCompletion.valid.poke(true.B)
        until(io.sourceCompletion.ready.peek().litToBoolean,"actual Publisher consumes VS completion")
        if(origin){io.cancelPatch.expect(true.B);io.cancelImage.expect(true.B)
          io.cancelSource.expect(false.B)}
        d.clock.step();io.sourceCompletion.valid.poke(false.B);io.sourceBusy.poke(false.B)
        if(origin)io.cancelSource.expect(true.B)
      }
      def imageResult(status:Int):Unit={
        if(status==0)until(!io.producerBusy.peek().litToBoolean,"image success follows actual Publisher completion transfer")
        io.imageCompletion.bits.status.poke(status.U);io.imageCompletion.bits.published.poke((if(status==0)1 else 0).U)
        io.imageCompletion.valid.poke(true.B);until(io.imageCompletion.ready.peek().litToBoolean,"actual image receipt")
        d.clock.step();io.imageCompletion.valid.poke(false.B)
      }
      def finish(status:Int,raw:Int):Unit={
        assert(!pending);until(io.completion.valid.peek().litToBoolean,"Owner waits for real Publisher and image drain")
        io.completion.bits.taskId.expect(id.U);io.completion.bits.status.expect(status.U)
        io.completion.bits.source.status.expect(raw.U);io.drained.expect(true.B)
        val held=io.completion.bits.peek().litValue
        io.cancel.poke(true.B);io.producerCancel.poke(true.B);io.transportDrained.poke(false.B)
        zero(io.begin.bits);io.begin.bits.vertex.taskId.poke(0xdead.U)
        for(_<-0 until 4){d.clock.step();io.completion.valid.expect(true.B)
          assert(io.completion.bits.peek().litValue==held,"closed Publisher/Owner held report changed")
          io.begin.ready.expect(false.B);io.drained.expect(false.B)}
        io.completion.ready.poke(true.B);d.clock.step();io.completion.ready.poke(false.B)
        io.cancel.poke(false.B);io.producerCancel.poke(false.B);io.begin.ready.expect(false.B)
        io.transportDrained.poke(true.B);io.begin.ready.expect(true.B);io.busy.expect(false.B)
      }
      def seal(cancel:Boolean=false):Unit={
        until(io.seal.valid.peek().litToBoolean,"real Publisher seal after every accepted reply and VS completion")
        if(cancel){io.cancel.poke(true.B);io.cancelSource.expect(true.B)}
        for(_<-0 until 3){io.seal.valid.expect(true.B);io.seal.bits.expect(true.B);d.clock.step()}
        io.seal.ready.poke(true.B);d.clock.step();io.seal.ready.poke(false.B)
      }
      // A native Publisher validation fault is not an external cancellation.
      begin(valid=false);until(io.cancelPatch.peek().litToBoolean,"Publisher captured layout fault")
      io.sourceDraw.valid.expect(false.B);io.cancelImage.expect(true.B);io.cancelSource.expect(false.B)
      d.clock.step();io.cancelSource.expect(true.B);imageResult(4);finish(2,1)
      // sourceFailed is combinational, but its noncancel fault remains primary.
      begin();heldDraw();sourceResult(1,origin=true);imageResult(4);finish(2,2)
      // External cancel reaches an owned Publisher immediately, while its VS
      // offer transfers before any downstream cancel is sent.
      begin();heldDraw(cancel=true);sourceResult(4);imageResult(4);finish(4,4)
      // A held patch write and its real abort reply cannot be discarded. A late
      // source fault must win over the earlier external cancellation.
      begin();heldDraw();vertex();load(cancel=true);sourceResult(1)
      reply(1);imageResult(4);finish(2,2)
      // An independent producer/payload cancellation stops the image immediately
      // and is latched before being returned to the Publisher on the next tick.
      begin();heldDraw();vertex();load(cancel=true,producer=true);sourceResult(4)
      reply(1);imageResult(4);finish(4,4)
      // Real patch-access faults also retain their raw Publisher status.
      begin();heldDraw();vertex();load();reply(2);sourceResult(0);imageResult(4);finish(2,3)
      // Even after all replies and source retirement, an offered seal survives
      // cancel until the actual seal acknowledgement transfers.
      begin();heldDraw();vertex();load();reply();sourceResult(0);seal(cancel=true)
      imageResult(4);finish(4,4)
      // Healthy final reuse without resetting either real controller.
      begin();heldDraw();vertex();load();reply();sourceResult(0);seal()
      imageResult(0);finish(0,0)
    }
  }

}
